            try:
                with loading_stopwatch('Fetching brokerage news online…'):news=google_news_rss(term,100)
                data={'rows':[{'Date':mc_date(n.get('published')),'Headline':n.get('title',''),'Source':n.get('source',''),'Link':n.get('link','')} for n in news], 'updated':datetime.now(ZoneInfo('Asia/Kolkata')).isoformat()};mc_cache_write(key,data)
            except Exception as exc:st.warning('Brokerage news request failed: '+str(exc))
