@st.cache_resource(show_spinner=False)
def dashboard_market_store():
    import sqlite3
    folder=Path('.nse_dashboard');folder.mkdir(exist_ok=True)
    state={'path':str(folder/'markets.sqlite3'),'lock':threading.RLock(),'cards':[dict(item) for item in DASHBOARD_MARKET_DEFAULTS],'quotes':{},'checked':'','crypto_live':{}}
    with sqlite3.connect(state['path']) as db:
        db.execute('CREATE TABLE IF NOT EXISTS settings(name TEXT PRIMARY KEY,payload TEXT)')
        for name,payload in db.execute('SELECT name,payload FROM settings'):
            try:state[name]=json.loads(payload)
            except Exception:pass
    if not state.get('crypto_added'):
        if not any(card.get('Symbol')=='CG:BELDEX' for card in state['cards']):state['cards'].append({'Name':'Beldex — BDX','Symbol':'CG:BELDEX','Display':'Crypto INR'})
        state['crypto_added']=True;dashboard_market_save(state)
    if not state.get('silverbees_added'):
        for card in state['cards']:
            if card.get('Symbol')=='SI=F':card.update(Name='SilverBeES',Symbol='SILVERBEES.NS',Display='INR')
        state['silverbees_added']=True;dashboard_market_save(state)
    state.setdefault('crypto_live',{})
    return state


def dashboard_market_save(state):
    import sqlite3
    with sqlite3.connect(state['path']) as db:
        for name in ['cards','quotes','checked','crypto_added','silverbees_added','crypto_live']:
            db.execute('INSERT OR REPLACE INTO settings VALUES (?,?)',(name,json.dumps(state.get(name,{} if name=='crypto_live' else False))))


def dashboard_market_series(card,quotes):
    source=quotes.get(card['Symbol'],[])
    if not source:return pd.Series(dtype=float,index=pd.DatetimeIndex([]))
    raw=pd.Series({pd.Timestamp(day):float(value) for day,value in source}).sort_index()
    if card['Display'] in ['Gold ₹/gram','Silver ₹/kg']:
        fx_source=quotes.get('INR=X',[])
        if not fx_source:return pd.Series(dtype=float,index=pd.DatetimeIndex([]))
        fx=pd.Series({pd.Timestamp(day):float(value) for day,value in fx_source}).sort_index()
        combined=fx.reindex(fx.index.union(raw.index)).sort_index().ffill()
        # Reject conversions without an FX observation in the preceding seven days.
        dates=pd.Series(fx.index,index=fx.index).reindex(combined.index).ffill()
        valid=[stamp for stamp in raw.index if stamp in dates.index and pd.notna(dates.loc[stamp]) and (stamp-dates.loc[stamp]).days<=7]
        raw=raw.reindex(valid)*combined.reindex(valid)/31.1034768
        if card['Display']=='Silver ₹/kg':raw=raw*1000
    return raw.replace([np.inf,-np.inf],np.nan).dropna()


def dashboard_indian_price(value):
    rounded=format(float(value),'.2f');whole,fraction=rounded.split('.')
    return fast_indian_share_format(int(whole))+'.'+fraction


def dashboard_move_date(delta):
    today=datetime.now(ZoneInfo('Asia/Kolkata')).date()
    st.session_state['dashboard_date']=min(today,st.session_state.get('dashboard_date',today)+timedelta(days=delta))


def dashboard_crypto_current(symbol, prefer_koinbx=True):
    if symbol.upper()=='CG:BELDEX' and prefer_koinbx:
        try:
            return dashboard_crypto_koinbx()
        except Exception:
            return dashboard_crypto_current(symbol, prefer_koinbx=False)
    coin=symbol.split(':',1)[1].lower()
    response=requests.get('https://api.coingecko.com/api/v3/simple/price',params={'ids':coin,'vs_currencies':'inr','include_24hr_change':'true','include_last_updated_at':'true'},headers=HEADERS,timeout=(5,15))
    response.raise_for_status();data=response.json().get(coin,{})
    price=float(data.get('inr',0));updated=int(data.get('last_updated_at',0))
    if not np.isfinite(price) or price<=0 or updated<=0:raise ValueError('Current crypto quote unavailable.')
    change=data.get('inr_24h_change')
    return {'price':price,'change':float(change) if change is not None and np.isfinite(float(change)) else None,'updated':updated,'source':'CoinGecko'}

def dashboard_crypto_koinbx():
    if True:
        response=requests.get('https://api.koinbx.com/markets',headers=HEADERS,timeout=(5,15))
        response.raise_for_status()
        market=next((row for row in response.json().get('markets',[]) if str(row.get('trading_pairs','')).upper()=='BDX_INR'),None)
        if not market:raise ValueError('KoinBX BDX/INR quote unavailable.')
        price=float(market.get('last_price',0))
        if not np.isfinite(price) or price<=0:raise ValueError('KoinBX BDX/INR price invalid.')
        raw=market.get('price_change_percent_24h')
        change=float(raw) if raw is not None else None
        if change is not None and not np.isfinite(change):change=None
        # Public markets endpoint supplies no exchange quote timestamp.
        return {'price':price,'change':change,'updated':int(datetime.now(ZoneInfo('Asia/Kolkata')).timestamp()),'source':'KoinBX BDX/INR','timestamp_kind':'retrieved'}


def dashboard_crypto_snapshot(symbol,selected):
    from urllib.parse import quote
    coin=symbol.split(':',1)[1].lower()
    rows=[]
    for day in [selected-timedelta(days=1),selected]:
        response=requests.get('https://api.coingecko.com/api/v3/coins/'+quote(coin,safe='')+'/history',params={'date':day.strftime('%d-%m-%Y'),'localization':'false'},headers=HEADERS,timeout=(5,15))
        response.raise_for_status()
        price=response.json().get('market_data',{}).get('current_price',{}).get('inr')
        if price is not None and np.isfinite(float(price)) and float(price)>0:rows.append([day.isoformat(),float(price)])
    return rows


@st.cache_resource(show_spinner=False)
def portfolio_store():
    import sqlite3
    folder=Path('.nse_portfolio');folder.mkdir(exist_ok=True)
    state={'path':str(folder/'portfolio.sqlite3'),'lock':threading.RLock(),'holdings':{'1':[],'2':[]},'quotes':{}}
    with sqlite3.connect(state['path']) as db:
        db.execute('CREATE TABLE IF NOT EXISTS data(name TEXT PRIMARY KEY,payload TEXT)')
        for name,payload in db.execute('SELECT name,payload FROM data'):
            try:state[name]=json.loads(payload)
            except Exception:pass
    return state


def portfolio_save(state):
    import sqlite3
    with sqlite3.connect(state['path']) as db:
        for name in ['holdings','quotes']:
            db.execute('INSERT OR REPLACE INTO data VALUES (?,?)',(name,json.dumps(state[name])))


def portfolio_validate_rows(frame):
    rows=[];seen=set()
    for _,row in frame.iterrows():
        if pd.isna(row.get('Stock')):raise ValueError('Enter a stock symbol for every row.')
        symbol=str(row['Stock']).strip().upper().removesuffix('.NS')
        if not re.fullmatch(r'[A-Z0-9&._-]{1,40}',symbol):raise ValueError('Enter valid NSE stock symbols.')
        if symbol in seen:raise ValueError(symbol+' appears twice. Keep one row with its total shares and average price.')
        try:quantity=float(row['Shares']);average=float(row['Average Price'])
        except (TypeError,ValueError):raise ValueError('Enter numeric shares and average prices.')
        if not np.isfinite(quantity) or quantity<=0 or not quantity.is_integer():raise ValueError('Shares must be a positive whole number.')
        if not np.isfinite(average) or average<=0:raise ValueError('Average purchase price must be positive.')
        seen.add(symbol);rows.append({'Stock':symbol,'Shares':int(quantity),'Average Price':average})
    return rows


def portfolio_values(holdings,quotes):
    rows=[];invested=0.0;priced_invested=0.0;current=0.0;missing=0
    for holding in holdings:
        symbol=holding['Stock'];quantity=int(holding['Shares']);average=float(holding['Average Price']);cost=quantity*average
        quote=quotes.get(symbol,{})
        price=quote.get('price');valid=price is not None and np.isfinite(float(price)) and float(price)>0
        invested+=cost
        if valid:
            value=quantity*float(price);profit=value-cost;current+=value;priced_invested+=cost
        else:value=profit=np.nan;missing+=1
        rows.append({'Stock':symbol,'Shares':quantity,'Average Price':average,'Latest Price':float(price) if valid else np.nan,'Invested':cost,'Current Value':value,'P/L ₹':profit,'P/L %':profit/cost*100 if valid else np.nan,'Quote Time (IST)':quote.get('time','Not loaded')})
    profit=current-priced_invested
    return pd.DataFrame(rows),{'invested':invested,'current':current,'profit':profit,'percent':profit/priced_invested*100 if priced_invested else np.nan,'missing':missing,'priced':len(holdings)-missing,'count':len(holdings)}


def portfolio_refresh(state,symbols):
    symbols=list(dict.fromkeys(symbols))
    if not symbols:return
    # Recent intraday quotes when available; provider may delay or return only the last trading session.
    for offset in range(0,len(symbols),50):
        batch=symbols[offset:offset+50]
        data,limited=limited_price_download([symbol+'.NS' for symbol in batch],period='5d',interval='5m',group_by='ticker',auto_adjust=False,progress=False)
        with state['lock']:
            for symbol in batch:
                frame=market_cache_frame(data,symbol,symbol+'.NS',len(batch))
                if frame.empty or 'Close' not in frame:continue
                closes=frame.Close.dropna()
                if closes.empty:continue
                price=float(closes.iloc[-1])
                if not np.isfinite(price) or price<=0:continue
                stamp=pd.Timestamp(closes.index[-1])
                stamp=stamp.tz_localize('Asia/Kolkata') if stamp.tzinfo is None else stamp.tz_convert('Asia/Kolkata')
                state['quotes'][symbol]={'price':price,'time':stamp.strftime('%d/%m/%Y %I:%M %p IST'),'checked':datetime.now(ZoneInfo('Asia/Kolkata')).strftime('%d/%m/%Y %I:%M %p IST')}
            portfolio_save(state)
        if limited:st.warning('Price provider limited requests. Saved quotes retained.');break


def portfolio_summary_card(title,totals):
    profit=totals['profit'];colour='#16a34a' if profit>=0 else '#dc2626'
    priced=totals['priced']>0
    value='₹'+dashboard_indian_price(totals['current']) if priced or totals['count']==0 else '—'
    pl=('+' if profit>=0 else '−')+'₹'+dashboard_indian_price(abs(profit)) if priced or totals['count']==0 else '—'
    percentage=f" ({totals['percent']:+.2f}%)" if pd.notna(totals['percent']) else ''
    suffix=' · partial' if totals['missing'] else ''
    st.markdown('<div style="padding:14px;border:1px solid #334155;border-radius:12px;background:#0d1726;color:#e2e8f0"><b>'+html.escape(title)+'</b><div style="margin-top:8px">Invested: ₹'+dashboard_indian_price(totals['invested'])+'</div><div>Current value'+suffix+': '+value+'</div><div style="color:'+colour+';font-weight:700">P/L'+suffix+': '+pl+percentage+'</div><small>'+str(totals['count'])+' holdings · '+str(totals['missing'])+' missing quotes</small></div>',unsafe_allow_html=True)


def render_portfolio_dashboard():
    state=portfolio_store()
    with state['lock']:
        one=list(state['holdings'].get('1',[]));two=list(state['holdings'].get('2',[]));quotes=dict(state['quotes'])
    st.markdown('### 💼 Portfolio')
    columns=st.columns(3)
    for column,label,holdings in zip(columns,['Portfolio 1','Portfolio 2','Combined'],[one,two,one+two]):
        with column:portfolio_summary_card(label,portfolio_values(holdings,quotes)[1])
    st.caption('Portfolio totals use saved quotes. Refresh prices in Portfolio. When quotes are missing, current value and P/L cover priced holdings only; invested amount covers every holding.')


def render_portfolio():
    st.markdown('## 💼 Portfolio')
    state=portfolio_store()
    chosen=st.radio('Portfolio',['1','2'],horizontal=True,key='portfolio_choice')
    st.caption('Enter NSE stocks / ETFs, whole shares and average purchase price in ₹. Holdings are saved separately for 1 and 2.')
    if st.button('Load NSE names for search',key='portfolio_names_load'):
        try:
            catalog=nse_sector_constituents('Total Market')
            st.session_state['portfolio_stock_names']=dict(zip(catalog.Symbol,catalog['Company Name']))
        except Exception:st.session_state['portfolio_stock_names']={symbol:symbol for symbol in universe()}
    names=st.session_state.get('portfolio_stock_names',{})
    symbols=sorted(set(names)|set(fast_percentage_store()['records'])|set(FALLBACK))
    with st.form('portfolio_add'):
        cols=st.columns([3,2,1,2])
        stock=cols[0].selectbox('Stock name / symbol',symbols,format_func=lambda symbol:symbol+' — '+str(names[symbol]) if symbol in names else symbol,key='portfolio_add_stock')
        manual=cols[1].text_input('Or NSE symbol',placeholder='SILVERBEES',key='portfolio_add_manual')
        quantity=cols[2].number_input('Shares',min_value=1,value=1,step=1,key='portfolio_add_qty')
        average=cols[3].number_input('Average price ₹',min_value=0.01,value=100.0,step=0.01,key='portfolio_add_avg')
        add=st.form_submit_button('Add holding',type='primary')
    if add:
        try:
            with state['lock']:
                existing=list(state['holdings'].get(chosen,[]))
                candidate={'Stock':manual.strip() or stock,'Shares':quantity,'Average Price':average}
                rows=portfolio_validate_rows(pd.DataFrame(existing+[candidate]))
                state['holdings'][chosen]=rows;portfolio_save(state)
            st.success('Holding saved. Click Refresh portfolio prices for its latest available quote.')
        except ValueError as exc:st.error(str(exc))
    with state['lock']:holdings=list(state['holdings'].get(chosen,[]))
    with st.expander('Edit / delete holdings'):
        st.caption('Edit shares or average price. Select a row and delete it to remove a holding, then Save changes.')
        edited=st.data_editor(pd.DataFrame(holdings,columns=['Stock','Shares','Average Price']),num_rows='dynamic',hide_index=True,use_container_width=True,key='portfolio_editor_'+chosen)
        if st.button('Save changes',key='portfolio_edit_save_'+chosen):
            try:
                rows=portfolio_validate_rows(edited)
                with state['lock']:state['holdings'][chosen]=rows;portfolio_save(state)
                holdings=rows;st.success('Changes saved.')
            except ValueError as exc:st.error(str(exc))
    if st.button('Refresh portfolio prices',type='primary',key='portfolio_quotes_refresh'):
        with loading_stopwatch('Refreshing portfolio prices…'):
            try:portfolio_refresh(state,[row['Stock'] for row in holdings])
            except Exception as exc:st.warning('Quote update failed; saved prices retained. '+str(exc))
    with state['lock']:frame,totals=portfolio_values(holdings,dict(state['quotes']))
    portfolio_summary_card('Portfolio '+chosen,totals)
    if frame.empty:st.info('Add your first holding above.');return
    def colour_profit(value):
        return 'color:#16a34a;font-weight:bold' if pd.notna(value) and value>=0 else 'color:#dc2626;font-weight:bold' if pd.notna(value) else ''
    shown=frame.style.map(colour_profit,subset=['P/L ₹','P/L %']).format({column:lambda value:'₹'+dashboard_indian_price(value) for column in ['Average Price','Latest Price','Invested','Current Value','P/L ₹']},na_rep='—').format({'P/L %':'{:+.2f}%'},subset=['P/L %'],na_rep='—')
    st.dataframe(shown,hide_index=True,use_container_width=True)
    st.caption('Latest prices are provider quotes and may be delayed or from an earlier trading session. P/L is unrealised and excludes brokerage, taxes, dividends and sold holdings. Quote timestamps are shown in IST.')
    st.download_button('Download portfolio '+chosen,frame.to_csv(index=False),'portfolio_'+chosen+'.csv','text/csv',key='portfolio_csv_'+chosen)


def render_market_dashboard():
    st.markdown('## 🏠 Market Dashboard')
    now=datetime.now(ZoneInfo('Asia/Kolkata'))
    st.caption(now.strftime('%d/%m/%Y · %I:%M %p IST')+' · Market cards use saved daily closes; Today’s crypto quote updates when you click Refresh.')
    state=dashboard_market_store()
    today=now.date()
    if 'dashboard_date' not in st.session_state:st.session_state['dashboard_date']=today
    nav=st.columns([1,4,1,2])
    nav[0].button('‹',key='dashboard_previous',on_click=dashboard_move_date,args=(-1,))
    selected=nav[1].date_input('Market date',format='DD/MM/YYYY',max_value=today,key='dashboard_date')
    nav[2].button('›',key='dashboard_next',on_click=dashboard_move_date,args=(1,),disabled=selected>=today)
    nav[3].button('Today',key='dashboard_today',on_click=lambda:st.session_state.update(dashboard_date=today))
    if st.button('Refresh market prices',type='primary',key='dashboard_refresh_markets'):
        with state['lock']:
            symbols=list(dict.fromkeys([card['Symbol'] for card in state['cards'] if card['Display']!='Crypto INR']+(['INR=X'] if any(card['Display'] in ['Gold ₹/gram','Silver ₹/kg'] for card in state['cards']) else [])))
        crypto_cards=[card for card in state['cards'] if card['Display']=='Crypto INR']
        for card in crypto_cards:
            try:
                if selected==today:
                    live=dashboard_crypto_current(card['Symbol'])
                    with state['lock']:
                        state.setdefault('crypto_live',{})[card['Symbol']]=live;dashboard_market_save(state)
                    continue
                rows=dashboard_crypto_snapshot(card['Symbol'],selected)
                with state['lock']:
                    existing=dict(state['quotes'].get(card['Symbol'],[]));existing.update(dict(rows))
                    state['quotes'][card['Symbol']]=sorted(existing.items());dashboard_market_save(state)
                if not rows:st.warning(card['Name']+': selected-date snapshot unavailable.')
            except Exception as exc:st.warning(card['Name']+': crypto snapshot unavailable; saved values kept. '+str(exc))
        if symbols:
            with loading_stopwatch('Refreshing dashboard markets…'):
                try:
                    download,limited=limited_price_download(symbols,start=(selected-timedelta(days=35)).isoformat(),end=(selected+timedelta(days=1)).isoformat(),interval='1d',group_by='ticker',auto_adjust=False,progress=False)
                    updated=0
                    with state['lock']:
                        for symbol in symbols:
                            frame=market_cache_frame(download,symbol,symbol,len(symbols))
                            if frame.empty or 'Close' not in frame:continue
                            rows=[]
                            for stamp,value in frame.Close.items():
                                if pd.notna(value) and np.isfinite(float(value)) and float(value)>0:
                                    rows.append([pd.Timestamp(stamp).date().isoformat(),float(value)])
                            if rows:
                                existing=dict(state['quotes'].get(symbol,[]));existing.update(dict(rows))
                                state['quotes'][symbol]=sorted(existing.items());updated+=1
                        state['checked']=datetime.now(ZoneInfo('Asia/Kolkata')).strftime('%d/%m/%Y %I:%M %p IST');dashboard_market_save(state)
                    if updated<len(symbols):st.warning(f'{updated}/{len(symbols)} symbols refreshed. Unavailable symbols retain earlier saved prices.')
                    if limited:st.warning('Provider rate limit reached. Saved prices retained.')
                except Exception as exc:st.warning('Refresh unavailable; saved prices retained. '+str(exc))
    with state['lock']:
        cards=[dict(card) for card in state['cards']];quotes=dict(state['quotes']);checked=state['checked'];crypto_live=dict(state.get('crypto_live',{}))
    if checked:st.caption('Last refresh attempt: '+checked)
    if not quotes and not crypto_live:st.info('Click Refresh market prices once to populate your cards.')
    if not cards:st.info('Add cards using Edit names / symbols above.');return
    for offset in range(0,len(cards),4):
        columns=st.columns(4)
        for col,card in zip(columns,cards[offset:offset+4]):
            with col:
                series=dashboard_market_series(card,quotes)
                if not series.empty:series=series[series.index<=pd.Timestamp(selected)]
                live=crypto_live.get(card['Symbol']) if selected==today and card['Display']=='Crypto INR' else None
                if card['Symbol']=='CG:BELDEX' and selected==today and not live:
                    st.markdown('**'+html.escape(card['Name'])+'**');st.caption('Beldex price not loaded — click Refresh market prices.');st.link_button('Open KoinBX BDX/INR','https://koinbx.com/trade/BDX-INR');continue
                if live:
                    updated=datetime.fromtimestamp(live['updated'],ZoneInfo('Asia/Kolkata'))
                    series=pd.Series([live['price']],index=pd.DatetimeIndex([pd.Timestamp(updated.date())]))
                unit='₹/gram' if card['Display']=='Gold ₹/gram' else '₹/kg' if card['Display']=='Silver ₹/kg' else '₹/coin' if card['Display']=='Crypto INR' else '₹' if card['Display']=='INR' else 'points'
                if series.empty:
                    st.markdown('**'+html.escape(card['Name'])+'**');st.caption('Price unavailable · '+unit);continue
                price=float(series.iloc[-1]);change=(price/float(series.iloc[-2])-1)*100 if len(series)>1 else np.nan
                if live:change=live.get('change') if live.get('change') is not None else np.nan
                value=dashboard_indian_price(price)
                if card['Display']!='Points':value='₹'+value
                else:value+=' pts'
                st.metric(card['Name'],value,f'{change:+.2f}%' if pd.notna(change) else None)
                st.caption(series.index[-1].strftime('%d/%m/%Y')+' · '+('₹/ETF unit' if card['Symbol']=='SILVERBEES.NS' else unit)+' · '+card['Symbol'])
                if live:
                    st.caption(('KoinBX BDX/INR · retrieved: ' if live.get('source')=='KoinBX BDX/INR' else 'CoinGecko quote: ')+updated.strftime('%d/%m/%Y %I:%M %p IST')+' · change over 24 hours')
