        st.caption("Quarterly ownership. Official NSE filing data is attempted first; Yahoo data is used only as fallback.")
        sh=PA_nse_shareholding(symbol)
        if not sh.empty:
            latest=sh.iloc[-1]; previous=sh.iloc[-2] if len(sh)>1 else None
